    "description": "36氪获悉，中信证券发布Q4大宗商品展望报告。报告称，印尼扩产及中东复产使中期电解铝供给压力上升，但海外边际产能成本及新增项目投资回报要求仍为铝价提供支撑，我们预计26Q4国内铝价为22500元/吨。碳酸锂当前库存仍低，但电池排产与锂盐采购需求增速或放缓，非洲锂精矿到港增加有望带动供应恢复，锂盐去库速度或随之放缓，价格面临调整压力。",
