    "content": "36氪获悉，华泰证券研报表示，2026年CTE中国玩具展&潮玩展于10月21-23日在上海举办，参观了多家头部潮玩公司展位，重点关注品牌出海、品类拓展及品牌建设进展。核心发现包括：1. 多种潮玩品类的欧美市场需求具备加速增长潜力，众多品牌“摩拳擦掌”，全球知名授权IP+中国创意及品质的组合拳潜力广阔；2. 国内市场正在消化高基数，价格带K型分化，体验+营销+渠道运营精细化，长尾企业出清利好龙头公司整合；3. 品类进一步向高端化、成人化突破，助力品牌心智建设。看好国内潮玩龙头持续打开全球市场的前景，2027-28年授…"
