    "content": "德国总统施泰因迈尔时隔八年再度访问中国，星期二（10月27日）凌晨抵达安徽，开启五天访华行程。 据中国央视新闻报道，施泰因迈尔乘机抵达合肥新桥国际机场。中国国家主席习近平将同施泰因迈尔会谈，总理李强、全国人大常委会委员长赵乐际将会见，就双边关系和共同关心的问题交换意见。 法新社报道，施泰因迈尔也将在星期四（29日）于北京大学发表演讲。施泰因迈尔办公室在声明中说，德中两国之间多元而复杂的关系，以及这些关系所带来的挑战，将是此行重点。 施泰因迈尔将于10月27日至31日对中国进行国事访问。中国外交部早前在介绍施泰因迈尔…"
