    "description": "2026年10月27日 新华社北京10月26日电 国务院总理李强日前签署国务院令，公布《事业单位登记管理条例》（以下简称《条例》），自2026年12月1日起施行。 《条例》旨在全面加强事业单位党的领导，强化事业单位公益性职责，规范事业单位登记管理，保障事业单位合法权益，发挥事业单位在经济社会高质量发展中的作用。《条例》共6章34条，主要内容如下： 一是明确事业单位登记管理的总体原则。规定事业单位登记管理工作应当坚持中国共产党的领导，坚持…",
