    "description": "2026年10月27日 秋风拂野，丰收礼赞奏响。稻田金黄、稻浪滚滚，神州大地迎来了丰收时节。 习近平总书记强调：“种业是最重要的，搞农业要把种业搞上去”“只有用自己的手攥紧中国种子，才能端稳中国饭碗，才能实现粮食安全”。 阵阵稻香，滋养着源远流长的稻作文化。作为世界上最早驯化水稻的国家，我国第一大口粮作物是水稻，60%以上人口以稻米为主食。岭南一带，细长、耐煮的丝苗米最宜制作煲仔饭，洁白的颗粒中腊味浓郁；东北平原，粳稻米浓缩了水土和温差…",
    "content": "2026年10月27日 秋风拂野，丰收礼赞奏响。稻田金黄、稻浪滚滚，神州大地迎来了丰收时节。 习近平总书记强调：“种业是最重要的，搞农业要把种业搞上去”“只有用自己的手攥紧中国种子，才能端稳中国饭碗，才能实现粮食安全”。 阵阵稻香，滋养着源远流长的稻作文化。作为世界上最早驯化水稻的国家，我国第一大口粮作物是水稻，60%以上人口以稻米为主食。岭南一带，细长、耐煮的丝苗米最宜制作煲仔饭，洁白的颗粒中腊味浓郁；东北平原，粳稻米浓缩了水土和温差的天赋，蒸煮后松软清香；滇南地区，大米经磨浆、发酵、压制，丝丝米线爽滑柔韧……一…"
