    "description": "2026年10月27日 老年人独自去大医院看病却找不到科室、不知道去哪里缴费取药；有些外地患者去其他城市的大医院“找不着北”……瞄准患者看病时的痛点，陪诊行业逐渐兴起，但因缺乏服务标准，存在边界模糊、服务质量参差不齐等问题。 由市场监管总局批准发布的《社会化陪同就医服务 基本要求》国家标准（GB/T 47801—2026）将于11月1日正式实施。新国标建立了涵盖陪诊服务提供者、服务内容、服务流程等各方面的服务框架。 谁可提供社会化陪诊服…",
    "content": "2026年10月27日 老年人独自去大医院看病却找不到科室、不知道去哪里缴费取药；有些外地患者去其他城市的大医院“找不着北”……瞄准患者看病时的痛点，陪诊行业逐渐兴起，但因缺乏服务标准，存在边界模糊、服务质量参差不齐等问题。 由市场监管总局批准发布的《社会化陪同就医服务&nbsp;&nbsp;基本要求》国家标准（GB/T 47801—2026）将于11月1日正式实施。新国标建立了涵盖陪诊服务提供者、服务内容、服务流程等各方面的服务框架。 谁可提供社会化陪诊服务？ 根据新国标，社会化陪诊服务提供者为“机构”。机构的陪…"
