    "content": "2026年10月27日 施泰因迈尔总统 \"> 应国家主席习近平邀请，德国总统施泰因迈尔将于10月27日至31日对中国进行国事访问。 弗兰克—瓦尔特·施泰因迈尔，1956年1月生于北莱茵—威斯特法伦州德特莫尔德市。德国吉森大学法学博士。施泰因迈尔1999年至2005年担任联邦总理施罗德办公室主任。2005年至2009年担任联邦外交部长（2007年11月起兼任联邦副总理）。2009年至2013年担任联邦议院社会民主党党团主席。2013年至2017年再次担任联邦外交部长。2017年2月当选德意志联邦共和国第十二任（第十六…"
