    "description": "2026年10月27日 10月26日上午，北京秋雨初霁、碧空如洗。中国人民革命军事博物馆，来自106个驻华使馆、5个国际组织的驻华使节和外交官参观“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”。 展览共分7个部分，展出照片图表357张、文物文献1061件（套），首次展出的文物文献有300余件，系统性展示了中国工农红军长征的光辉历程、伟大意义和深远影响。在一件件历史文物、老照片、影像资料前，驻华使节和外交官们频频举起手机拍照，…",
    "content": "2026年10月27日 10月26日上午，北京秋雨初霁、碧空如洗。中国人民革命军事博物馆，来自106个驻华使馆、5个国际组织的驻华使节和外交官参观“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”。 展览共分7个部分，展出照片图表357张、文物文献1061件（套），首次展出的文物文献有300余件，系统性展示了中国工农红军长征的光辉历程、伟大意义和深远影响。在一件件历史文物、老照片、影像资料前，驻华使节和外交官们频频举起手机拍照，不时向工作人员提问。 “伟大长征精神是宝贵的历史遗产，不仅属于中国人民，也属于整…"
