    "description": "2026年10月27日 地震发生后，索县人民医院第一时间启动应急响应：预检分诊、分类救治、转诊转运，有条不紊。急诊通道的灯一直亮着，伤员进来，很快被分流到该去的地方；需要转院的，转运车辆随即出发。这样迅速有序的响应，靠的是平时持续的人才培训、救治流程的一遍遍打磨，把这些基础打牢了，关键时刻才转得快。 震后没多久，基层干部已经在挨家挨户摸排：哪村哪户什么情况、老人孩子多少、缺什么、急什么，台账里写得清清楚楚。这份清楚，靠的是平时常态化的走…",
    "content": "2026年10月27日 地震发生后，索县人民医院第一时间启动应急响应：预检分诊、分类救治、转诊转运，有条不紊。急诊通道的灯一直亮着，伤员进来，很快被分流到该去的地方；需要转院的，转运车辆随即出发。这样迅速有序的响应，靠的是平时持续的人才培训、救治流程的一遍遍打磨，把这些基础打牢了，关键时刻才转得快。 震后没多久，基层干部已经在挨家挨户摸排：哪村哪户什么情况、老人孩子多少、缺什么、急什么，台账里写得清清楚楚。这份清楚，靠的是平时常态化的走访和扎实的基层治理。 地震后，学校里孩子们撤离迅速有序。警报一响，往哪跑、怎么集…"
