    "description": "2026年10月27日 新华社北京10月14日电 原国家机械工业局局长、党组书记邵奇惠同志（正部长级），因病于2026年9月17日在北京逝世，享年92岁。 邵奇惠同志逝世后，中央有关领导同志以不同方式表示哀悼并向其亲属表示慰问。 邵奇惠，1934年6月生，江苏宜兴人。1952年9月参加工作，1953年10月加入中国共产党。1955年2月至1958年3月先后任青年团浙江省杭州市委办公室副主任、共青团浙江省杭州市委学校工作部副部长。1962…",
    "content": "2026年10月27日 新华社北京10月14日电&nbsp;&nbsp;原国家机械工业局局长、党组书记邵奇惠同志（正部长级），因病于2026年9月17日在北京逝世，享年92岁。 邵奇惠同志逝世后，中央有关领导同志以不同方式表示哀悼并向其亲属表示慰问。 邵奇惠，1934年6月生，江苏宜兴人。1952年9月参加工作，1953年10月加入中国共产党。1955年2月至1958年3月先后任青年团浙江省杭州市委办公室副主任、共青团浙江省杭州市委学校工作部副部长。1962年2月至1985年5月曾先后任哈尔滨林业机械厂副厂长、总工…"
