    "description": "2026年10月27日 “长满了红锈的鱼钩上，闪烁着灿烂的金色的光芒”……一个名为“郝家豁”的创作团队将《金色的鱼钩》等长征题材课文拍成短片，获得广泛关注。课本承载的集体记忆在网络上引发了情感共鸣，也让先烈的事迹在光影中赓续流传。有网友点赞：“这就是语文课本最棒的‘续集’”。 新中国成立以来，中小学教材历经多轮修订，篇目有所增删，文本不断打磨。《金色的鱼钩》《老山界》《七律·长征》等长征题材课文长期留存于课本中，陪伴一代代人成长，沉淀为…",
    "content": "2026年10月27日 “长满了红锈的鱼钩上，闪烁着灿烂的金色的光芒”……一个名为“郝家豁”的创作团队将《金色的鱼钩》等长征题材课文拍成短片，获得广泛关注。课本承载的集体记忆在网络上引发了情感共鸣，也让先烈的事迹在光影中赓续流传。有网友点赞：“这就是语文课本最棒的‘续集’”。 新中国成立以来，中小学教材历经多轮修订，篇目有所增删，文本不断打磨。《金色的鱼钩》《老山界》《七律·长征》等长征题材课文长期留存于课本中，陪伴一代代人成长，沉淀为共同的阅读记忆。 红色文学佳作浩如烟海，为何长征题材经久不衰？文字背后，精神力量…"
