    "description": "2026年10月27日 受访者供图 \"> 10月的贵州省息烽县，秋高气爽，阳光从树叶间斑驳洒下，成片的黄菊、白菊随风摇曳。青山苗族乡绿化村的小广场上，村民们身着民族服饰，吹奏着芦笙，欢迎黄振贵再度到来。 来自江西九江的黄振贵，是一名年过六旬的老党员。一个背包、一个人，343天、8000多公里，从江西于都到陕西吴起。去年退休后，黄振贵完成了“一个人的长征”。重走长征路的第194天，他走到息烽，结下了一段情缘。 很多人问他，这么大年纪，为什…",
    "content": "2026年10月27日 黄振贵在徒步中。 受访者供图 \"> 10月的贵州省息烽县，秋高气爽，阳光从树叶间斑驳洒下，成片的黄菊、白菊随风摇曳。青山苗族乡绿化村的小广场上，村民们身着民族服饰，吹奏着芦笙，欢迎黄振贵再度到来。 来自江西九江的黄振贵，是一名年过六旬的老党员。一个背包、一个人，343天、8000多公里，从江西于都到陕西吴起。去年退休后，黄振贵完成了“一个人的长征”。重走长征路的第194天，他走到息烽，结下了一段情缘。 很多人问他，这么大年纪，为什么要重走长征路？ “我是江西人，从小就听着长征的故事长大，很早…"
