    "description": "2026年10月27日 东北虎豹国家公园地处吉林、黑龙江两省交界的老爷岭南部，东部与俄罗斯豹地国家公园接壤，总面积1.41万平方公里，是野生东北虎、东北豹在中国唯一的稳定繁殖栖息地。这里是我国首批设立的5个国家公园之一，也是唯一承担跨境保护任务的国家公园。 高质量建设东北虎豹国家公园，是中国生态文明建设在东北林海的具体实践，也是美丽中国新画卷上浓墨重彩的一笔。 东北虎豹国家公园有其独特性——大部分区域海拔200—600米，百余个村屯、数…",
    "content": "2026年10月27日 东北虎豹国家公园地处吉林、黑龙江两省交界的老爷岭南部，东部与俄罗斯豹地国家公园接壤，总面积1.41万平方公里，是野生东北虎、东北豹在中国唯一的稳定繁殖栖息地。这里是我国首批设立的5个国家公园之一，也是唯一承担跨境保护任务的国家公园。 高质量建设东北虎豹国家公园，是中国生态文明建设在东北林海的具体实践，也是美丽中国新画卷上浓墨重彩的一笔。 东北虎豹国家公园有其独特性——大部分区域海拔200—600米，百余个村屯、数万居民散落其间，既不能把人迁走了事或把虎豹关进围栏，也不能让老百姓守着金山过苦日…"
