    "description": "2026年10月27日 本报香港10月26日电 （记者李霞）26日，“一带一路”绿色创新大会2026在香港举行。本次会议由生态环境部和香港特别行政区政府环境及生态局共同主办，“一带一路”绿色发展国际联盟、生态环境部对外合作与交流中心、香港特别行政区环境保护署承办，来自20余个国家近300人出席会议。大会以“携手南方绿色转型，共促全球可持续发展”为主题，就绿色金融、绿色创新、数智赋能等多个议题作深入交流。 生态环境部部长黄润秋致辞时表示，…",
    "content": "2026年10月27日 本报香港10月26日电&nbsp;&nbsp;（记者李霞）26日，“一带一路”绿色创新大会2026在香港举行。本次会议由生态环境部和香港特别行政区政府环境及生态局共同主办，“一带一路”绿色发展国际联盟、生态环境部对外合作与交流中心、香港特别行政区环境保护署承办，来自20余个国家近300人出席会议。大会以“携手南方绿色转型，共促全球可持续发展”为主题，就绿色金融、绿色创新、数智赋能等多个议题作深入交流。 生态环境部部长黄润秋致辞时表示，中国坚定不移走生态优先、绿色发展之路，始终做世界绿色发展的…"
