    "description": "2026年10月27日 秋日午后，江苏省苏州市姑苏区的桂花公园里暗香浮动。循香而入，一场处处融入桂花元素的桂花市集十分热闹：或设计成随身佩饰、案头摆件，或化身桂花奶昔、入口即化的冰激凌，还有花香馥郁的化妆品、香皂……摊位鳞次栉比，吸引游客驻足。一朵苏州市花，“变”出了各种消费新场景。 在网上做足攻略的00后上海游客王佳怡一下火车，就直奔桂花公园。到了市集，第一站就来到了苏州老字号“月中桂”的摊位前，在这里，桂花香被融入护手霜、香水，随手…",
    "content": "2026年10月27日 秋日午后，江苏省苏州市姑苏区的桂花公园里暗香浮动。循香而入，一场处处融入桂花元素的桂花市集十分热闹：或设计成随身佩饰、案头摆件，或化身桂花奶昔、入口即化的冰激凌，还有花香馥郁的化妆品、香皂……摊位鳞次栉比，吸引游客驻足。一朵苏州市花，“变”出了各种消费新场景。 在网上做足攻略的00后上海游客王佳怡一下火车，就直奔桂花公园。到了市集，第一站就来到了苏州老字号“月中桂”的摊位前，在这里，桂花香被融入护手霜、香水，随手涂一涂、喷一喷，淡淡的桂花香便萦绕周身。还有加入桂花精油的香皂，也让她十分心动。…"
