    "author": "",
    "description": "2026年10月27日 稻满仓，果飘香，又是一年丰收时。广袤的乡村大地，既种得出农业发展的底气，也有茁壮生长的文艺“新庄稼”。 文艺“新庄稼”的样态，展现乡村的独特内涵。江苏兴农村以画入村，山东王哥庄办起“大馒头文化季”，文艺成为展现地方风韵的窗口。 文艺“新庄稼”的收获，也为乡村的发展添彩。一场“村晚”丰富了农民精神生活，乡村阅读、写作让农家生活盈满书香，蓬勃发展的乡村文艺也为地方文旅与产业发展带来“好收成”。 我们期待文艺更好地扎根…",
    "content": "2026年10月27日 稻满仓，果飘香，又是一年丰收时。广袤的乡村大地，既种得出农业发展的底气，也有茁壮生长的文艺“新庄稼”。 文艺“新庄稼”的样态，展现乡村的独特内涵。江苏兴农村以画入村，山东王哥庄办起“大馒头文化季”，文艺成为展现地方风韵的窗口。 文艺“新庄稼”的收获，也为乡村的发展添彩。一场“村晚”丰富了农民精神生活，乡村阅读、写作让农家生活盈满书香，蓬勃发展的乡村文艺也为地方文旅与产业发展带来“好收成”。 我们期待文艺更好地扎根田野，让更多人品尝文化丰收的甘甜。 2026-10-27 00:00:00:0 …"
