    "description": "2026年10月27日 “从现在起，请大家记住，自己不再是大学生……到底谁藏有秘密？请展开推理。”近日，武汉理工大学图书馆余家头分馆举办了一场红色主题“风声·谍影”沉浸式推理阅读活动。活动以谍战小说《风声》为蓝本，12名同学代入角色，参与其中。 “我们像当年的地下工作者一样甄别信息、辨别真伪，真切体会到情报工作的艰难，感受到先辈坚守信仰、临危不惧的勇气。后续我打算阅读更多红色经典，更完整地了解这段历史。”该校航运学院2025级学生谢吉翔…",
    "content": "2026年10月27日 “从现在起，请大家记住，自己不再是大学生……到底谁藏有秘密？请展开推理。”近日，武汉理工大学图书馆余家头分馆举办了一场红色主题“风声·谍影”沉浸式推理阅读活动。活动以谍战小说《风声》为蓝本，12名同学代入角色，参与其中。 “我们像当年的地下工作者一样甄别信息、辨别真伪，真切体会到情报工作的艰难，感受到先辈坚守信仰、临危不惧的勇气。后续我打算阅读更多红色经典，更完整地了解这段历史。”该校航运学院2025级学生谢吉翔说。 “随着电子阅读的普及，如何让学生们亲近图书、爱上深度阅读，这是我们图书馆十…"
