    "category": "新闻",
    "title": "13版 - 中国工程院开展学习“两弹一星”精神活动",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202610/27/content_30187836.html",
    "pub_date": "2026-10-27 08:26:03",
    "author": "",
    "description": "2026年10月27日 本报北京10月26日电 （记者谷业凯）为大力弘扬“两弹一星”精神和科学家精神，中国工程院近日组织院士赴新疆马兰基地开展学习“两弹一星”精神活动。 工程院一行瞻仰了马兰烈士陵园和中国工程院首任院长朱光亚题写碑额的马兰革命烈士纪念碑，向革命先烈敬献花篮，实地参观了历史展览馆、林俊德纪念馆、红山军博园和实景式展示区等教育阵地，并举行中国工程院学习“两弹一星”精神座谈会，实地感受老一辈科技工作者的崇高品格和“两弹一星”精…",
    "content": "2026年10月27日 本报北京10月26日电&nbsp;&nbsp;（记者谷业凯）为大力弘扬“两弹一星”精神和科学家精神，中国工程院近日组织院士赴新疆马兰基地开展学习“两弹一星”精神活动。 工程院一行瞻仰了马兰烈士陵园和中国工程院首任院长朱光亚题写碑额的马兰革命烈士纪念碑，向革命先烈敬献花篮，实地参观了历史展览馆、林俊德纪念馆、红山军博园和实景式展示区等教育阵地，并举行中国工程院学习“两弹一星”精神座谈会，实地感受老一辈科技工作者的崇高品格和“两弹一星”精神。 院士们说，要继续践行“两弹一星”精神，为建设科技强国…"
