    "description": "2026年10月27日 本报西安10月26日电 （记者高炳）记者从陕西西安秦始皇帝陵博物院获悉：该院与山东大学考古学院合作完成了一项关于秦兵马俑制作者年龄与性别构成的研究。这项基于陶俑表面指纹的研究近日发表于国际文化遗产研究期刊《文化遗产杂志》，研究发现秦俑制作中，可能有女性和少年参与。 研究团队对秦始皇帝陵博物院一号坑T23探方23件陶俑上保存的指纹印痕进行提取，共获得79枚独立指纹样本，并引入近年提出的指纹贝叶斯混合模型研究方法，从…",
    "content": "2026年10月27日 本报西安10月26日电&nbsp;&nbsp;（记者高炳）记者从陕西西安秦始皇帝陵博物院获悉：该院与山东大学考古学院合作完成了一项关于秦兵马俑制作者年龄与性别构成的研究。这项基于陶俑表面指纹的研究近日发表于国际文化遗产研究期刊《文化遗产杂志》，研究发现秦俑制作中，可能有女性和少年参与。 研究团队对秦始皇帝陵博物院一号坑T23探方23件陶俑上保存的指纹印痕进行提取，共获得79枚独立指纹样本，并引入近年提出的指纹贝叶斯混合模型研究方法，从群体层面对指纹的年龄与性别结构进行推测。 研究结果表明，本…"
