    "description": "2026年10月27日 2026年10月17日，国务院总理李强签署第849号国务院令，公布《事业单位登记管理条例》（以下简称《条例》），自2026年12月1日起施行。日前，中央编办、司法部负责人就《条例》有关问题回答了记者提问。 问：请介绍一下条例修订的背景和总体思路。 答：党中央高度重视事业单位改革。习近平总书记作出一系列重要论述和重要指示，为全面深化事业单位改革、推动事业单位高质量发展指明方向。党中央、国务院对深化事业单位改革作出新…",
    "content": "2026年10月27日 2026年10月17日，国务院总理李强签署第849号国务院令，公布《事业单位登记管理条例》（以下简称《条例》），自2026年12月1日起施行。日前，中央编办、司法部负责人就《条例》有关问题回答了记者提问。 问：请介绍一下条例修订的背景和总体思路。 答：党中央高度重视事业单位改革。习近平总书记作出一系列重要论述和重要指示，为全面深化事业单位改革、推动事业单位高质量发展指明方向。党中央、国务院对深化事业单位改革作出新部署，提出新要求。事业单位在提供公共服务、保障基本民生方面承担着重要职能。《事业…"
