    "description": "2026年10月27日 以上图片均为新华社记者翁忻旸摄 \"> 北京时间10月26日凌晨，为期8天的第五十四届世界体操锦标赛（以下简称“世锦赛”）在荷兰鹿特丹落下帷幕。中国体操队发挥亮眼，取得3金2银2铜的成绩，并顺利获得洛杉矶奥运会男、女团体参赛资格。 “中国体操队在男、女团体和男、女个人全能项目均获得奖牌，为队伍参加世锦赛68年来首次。”国家体育总局体操运动管理中心主任常成表示，队伍的整体表现达到赛前预期，接下来力争取得更好的成绩。 …",
