    "description": "2026年10月27日 等电梯时做几个深蹲，接电话时起身快走，洗碗时踮踮脚尖……一种把运动像零食一样“拆着吃”的“零食运动法”近来在社交平台上受到追捧。有网友直呼“没想到等咖啡的时候也能锻炼燃脂”。这种不挑时间、不挑场地的运动方式管用吗？ 首都体育学院体医融合创新中心教授郭建军表示，“零食运动法”是把运动化整为零，利用一天里的时间和空间缝隙，见缝插针地动起来。“它可以短到二三十秒，长到十来分钟，等公交时的小跑、错过电梯后的爬楼、陪孩子在…",
    "content": "2026年10月27日 等电梯时做几个深蹲，接电话时起身快走，洗碗时踮踮脚尖……一种把运动像零食一样“拆着吃”的“零食运动法”近来在社交平台上受到追捧。有网友直呼“没想到等咖啡的时候也能锻炼燃脂”。这种不挑时间、不挑场地的运动方式管用吗？ 首都体育学院体医融合创新中心教授郭建军表示，“零食运动法”是把运动化整为零，利用一天里的时间和空间缝隙，见缝插针地动起来。“它可以短到二三十秒，长到十来分钟，等公交时的小跑、错过电梯后的爬楼、陪孩子在客厅里玩到气喘吁吁，都算在内。它最大的价值，是把运动的门槛降到很低。” 《202…"
