    "description": "2026年10月27日 新华社发 \"> 西非经济货币联盟近期发布的《2026年10月区域经济形势报告》显示，2026年该联盟8个成员国整体经济增速预计为6.3%，全年平均通胀率约为1.2%。非洲开发银行此前预测，西非地区今年经济增长4.7%，高于非洲大陆4.2%的平均增速。国际货币基金组织预计，几内亚、科特迪瓦、贝宁等多个西非国家2026年增速有望突破6%，西非仍是非洲经济增长的重要引擎。 当前，西非经济总体保持较强韧性，内需扩大、投资…",
    "content": "2026年10月27日 在科特迪瓦阿博维尔，当地民众收获可可果。 新华社发 \"> 西非经济货币联盟近期发布的《2026年10月区域经济形势报告》显示，2026年该联盟8个成员国整体经济增速预计为6.3%，全年平均通胀率约为1.2%。非洲开发银行此前预测，西非地区今年经济增长4.7%，高于非洲大陆4.2%的平均增速。国际货币基金组织预计，几内亚、科特迪瓦、贝宁等多个西非国家2026年增速有望突破6%，西非仍是非洲经济增长的重要引擎。 当前，西非经济总体保持较强韧性，内需扩大、投资增长、服务业回暖与工农业稳步发展为经济…"
