    "content": "新华社大马士革/安曼10月27日电（记者林建杰 何奕萍）叙利亚过渡政府应急与灾害管理部27日凌晨发表声明说，约旦空军26日晚袭击叙南部德拉省和苏韦达省农村地区多个地点，造成包括妇女儿童在内7人死亡，另有3人受伤。叙利亚过渡政府口岸与海关总署宣布关闭与约旦接壤的纳西卜口岸。 声明说，约旦空军击中德拉省东北部一顶帐篷，造成一个家庭5死3伤。德拉省南部一处农场和苏韦达省北部一处民宅遭袭，两名平民死亡。德拉省西部一处民宅遭袭，未造成人员伤亡。 声明说，救援队接到袭击报告后，前往受袭地点开展救援，搜寻并转移遇难者遗体。 叙过…"
