    "content": "新华社巴西利亚10月26日电（记者吴昊）巴西副总统阿尔克明26日接受巴西媒体采访，驳斥美国总统特朗普关于巴西总统选举疑似“被操纵”的言论以及他对延长投票时长的质疑。 阿尔克明表示，“首先，不干涉他国内政是基本原则。其次，没有任何证据支持这种说法”。他指出，巴西选举有电子投票系统和法律保障，选举输赢完全由巴西人民决定。巴西高等选举法院数据显示，即便投票时长未延长，劳工党候选人、现任总统卢拉仍会获胜。 特朗普26日稍早时候称，巴西总统选举“看起来像被操纵”，他还称延长投票时长“非常奇怪”。对此，巴西媒体援引巴西高等选举…"
